def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    best = None
    for axis in (0, 1):
        L = g.shape[axis]
        for p in range(2, L // 3 + 1):
            if L % p:
                continue
            n = L // p
            pans = [g[k*p:(k+1)*p, :] if axis == 0 else g[:, k*p:(k+1)*p] for k in range(n)]
            T = pans[-1]
            fm = T != bg
            if all(np.array_equal(P[fm], T[fm]) for P in pans):
                best = (pans, T)
                break
        if best:
            break
    pans, T = best
    n = len(pans)
    out = T.copy()
    emit(out, "Allocate the next panel: a copy of the empty frame panel at the end of the strip.")

    def colset(P):
        return frozenset(np.unique(P[P != T]).tolist())

    q = 1
    for cand in range(1, n - 1):
        ok = all(colset(pans[k]) == colset(pans[k - cand]) for k in range(cand, n - 1))
        if ok and n - 1 - 2 * cand >= 0:
            q = cand
            break
    A_p, B_p = pans[n - 1 - 2 * q], pans[n - 1 - q]

    def objs(P):
        mask = P != T
        res = []
        for cells in components(mask):
            y0, x0, y1, x1 = bbox(cells)
            sub = np.full((y1 - y0 + 1, x1 - x0 + 1), -1)
            for y, x in cells:
                sub[y - y0, x - x0] = P[y, x]
            cs = frozenset(int(P[y, x]) for y, x in cells)
            res.append((cs, y0, x0, sub))
        return res

    oa, ob = objs(A_p), objs(B_p)
    used = set()

    def extend(a, b):
        # b equals a with rows inserted at some index; insert those rows again
        d = b.shape[0] - a.shape[0]
        if d == 0:
            return b
        for i in range(a.shape[0] + 1):
            if np.array_equal(b[:i], a[:i]) and np.array_equal(b[i + d:], a[i:]):
                return np.vstack([b[:i], b[i:i + d], b[i:]])
        return b

    for cs, by, bx, bsub in ob:
        match = None
        for j, (ca, ay, ax, asub) in enumerate(oa):
            if j not in used and ca == cs:
                match = j
                break
        if match is None:
            continue
        used.add(match)
        _, ay, ax, asub = oa[match]
        c = bsub
        if asub.shape[1] != bsub.shape[1] and asub.shape[0] == bsub.shape[0]:
            c = extend(asub.T, bsub.T).T
        elif asub.shape[0] != bsub.shape[0] and asub.shape[1] == bsub.shape[1]:
            c = extend(asub, bsub)
        cy, cx = by + (by - ay), bx + (bx - ax)
        for y in range(c.shape[0]):
            for x in range(c.shape[1]):
                if c[y, x] >= 0 and 0 <= cy + y < out.shape[0] and 0 <= cx + x < out.shape[1]:
                    out[cy + y, cx + x] = c[y, x]
        emit(out, f"Draw the next growth step of the object with colours {sorted(cs)}: "
                  f"repeat the block it gained between the two previous steps and shift it by the same offset.")
    emit(out, "Final panel: the next frame of the sequence.")
    return out
